// @vitest-environment node
// Task 19.2, requirement 13.6: the pre-check never rejects a geometry the server accepts.
// `geometryPrecheck.test.ts` already runs every vector. This file makes the accepted-vector
// check explicit and non-vacuous, and tries the accepted shapes with a different ring order.
import { readFileSync } from 'node:fs'
import fc from 'fast-check'
import { geometryPrecheck } from './geometryPrecheck'

// Synthetic shapes generated by the Python geometry module, not NASA data.
type Vector = {
  name: string
  geometry?: { type: 'Polygon' | 'MultiPolygon'; coordinates: unknown }
  expected: { valid: boolean; reason: string | null; vertex_count: number | null }
}
const file = JSON.parse(
  readFileSync(new URL('../../../tests/data/selection_vectors.json', import.meta.url), 'utf8'),
) as { vectors: Vector[] }

const accepted = file.vectors.filter((v) => v.geometry !== undefined && v.expected.valid)

type Ring = number[][]
type Polygon = Ring[]

function polygonsOf(geometry: NonNullable<Vector['geometry']>): Polygon[] {
  return geometry.type === 'Polygon'
    ? [geometry.coordinates as Polygon]
    : (geometry.coordinates as Polygon[])
}

/** Same shape with each ring started at another vertex and optionally reversed. */
function reorder(polygons: Polygon[], shift: number, reverse: boolean): Polygon[] {
  return polygons.map((polygon) =>
    polygon.map((ring) => {
      const open = ring.slice(0, -1)
      const k = shift % open.length
      const rotated = [...open.slice(k), ...open.slice(0, k)]
      const ordered = reverse ? rotated.reverse() : rotated
      return [...ordered, ordered[0] as number[]]
    }),
  )
}

describe('geometryPrecheck on geometries the server accepts (Requirement 13.6)', () => {
  it('has accepted vectors that include a hole, a multipolygon and 1000 vertices', () => {
    const names = accepted.map((v) => v.name)
    expect(names).toEqual(
      expect.arrayContaining([
        'valid_polygon_with_hole',
        'valid_multipolygon',
        'valid_1000_vertices',
        'valid_partly_outside_east',
      ]),
    )
  })

  it.each(accepted.map((v) => [v.name, v] as const))('accepts %s', (_name, vector) => {
    const result = geometryPrecheck(vector.geometry)
    expect(result.ok).toBe(true)
    expect(result.vertexCount).toBe(vector.expected.vertex_count)
  })

  it('still accepts them with another start vertex or the opposite ring direction', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...accepted),
        fc.nat({ max: 2000 }),
        fc.boolean(),
        (vector, shift, reverse) => {
          const geometry = vector.geometry as NonNullable<Vector['geometry']>
          const coordinates = reorder(polygonsOf(geometry), shift, reverse)
          const changed =
            geometry.type === 'Polygon'
              ? { type: 'Polygon', coordinates: coordinates[0] }
              : { type: 'MultiPolygon', coordinates }
          expect(geometryPrecheck(changed).ok).toBe(true)
        },
      ),
    )
  })
})
